from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)

        for i, num in enumerate(nums):
            prefix[i + 1] = prefix[i] + num

        neg_inf = -10**18
        dp = [0] * (n + 1)

        for count in range(1, k + 1):
            ndp = [neg_inf] * (n + 1)
            best = neg_inf

            for i in range(count * m, n + 1):
                start_pos = i - m
                best = max(best, dp[start_pos] - prefix[start_pos])
                ndp[i] = max(ndp[i - 1], prefix[i] + best)

            dp = ndp

        return dp[n]
